from dataclasses import dataclass
from enum import Enum
from metrics import BreakerMetricsRecord
from policies import BreakerPolicyRecord


class BreakerState(str, Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


@dataclass
class CircuitBreaker:
    policy: BreakerPolicyRecord
    state: BreakerState = BreakerState.CLOSED
    failures: int = 0
    opened_at: int | None = None
    in_flight_probe: bool = False
    metrics: BreakerMetricsRecord | None = None

    def allow_request(self, now: int) -> bool:
        if self.state == BreakerState.CLOSED:
            return True
        if self.state == BreakerState.OPEN:
            if self.opened_at is not None and now - self.opened_at >= self.policy.metadata.get("reset_after", 30):
                self.state = BreakerState.HALF_OPEN
                self.in_flight_probe = False
            else:
                self._record("rejected")
                return False
        if self.state == BreakerState.HALF_OPEN:
            self.in_flight_probe = True
            return True
        return False

    def record_success(self) -> None:
        self._record("success")
        if self.state == BreakerState.HALF_OPEN:
            self.state = BreakerState.CLOSED
            self.failures = 0
            self.opened_at = None
            self.in_flight_probe = False
        elif self.state == BreakerState.CLOSED:
            self.failures = 0

    def record_failure(self, now: int) -> None:
        self._record("failure")
        self.failures += 1
        if self.state == BreakerState.HALF_OPEN or self.failures >= self.policy.metadata.get("failure_threshold", 3):
            self.state = BreakerState.OPEN
            self.opened_at = now
            self.in_flight_probe = False

    def _record(self, outcome: str) -> None:
        if self.metrics is not None:
            self.metrics.metadata[outcome] = self.metrics.metadata.get(outcome, 0) + 1


def call_with_breaker(breaker: CircuitBreaker, provider, *, now: int) -> dict:
    if not breaker.allow_request(now):
        return {"ok": False, "state": breaker.state.value, "reason": "breaker_open"}
    try:
        value = provider()
    except Exception:
        breaker.record_failure(now)
        return {"ok": False, "state": breaker.state.value, "reason": "provider_error"}
    breaker.record_success()
    return {"ok": True, "state": breaker.state.value, "value": value}

# Operational helpers used by this challenge domain.
BREAKER_DOMAIN_TERMS = ('breaker', 'provider', 'probe', 'recovery')

class BreakerLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def breaker_compact_metadata(metadata):
    """Return public breaker metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def breaker_merge_context(base, extra):
    """Merge provider context without mutating caller-owned dictionaries."""
    merged = breaker_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def breaker_labels(records, key="name"):
    """Extract labels for probe diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def breaker_group_by_status(records, key="status"):
    """Group recovery records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def breaker_summary(records, key="status"):
    """Count breaker records by status."""
    return {name: len(items) for name, items in breaker_group_by_status(records, key).items()}

