    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field_name} must be an integer") from exc
    if parsed < 0:
        raise ValueError(f"{field_name} must be non-negative")
    return parsed


def stable_partition(records: list[BreakerMetricsRecord], state: str) -> tuple[list[BreakerMetricsRecord], list[BreakerMetricsRecord]]:
    matching: list[BreakerMetricsRecord] = []
    remaining: list[BreakerMetricsRecord] = []
    for record in records:
        if record.state == state:
            matching.append(record)
        else:
            remaining.append(record)
    return matching, remaining


def summarize(records: list[BreakerMetricsRecord]) -> dict[str, int]:
