import pytest
from breaker import BreakerState, CircuitBreaker, call_with_breaker
from policies import BreakerPolicyRecord


def policy():
    return BreakerPolicyRecord("tax", metadata={"failure_threshold": 2, "reset_after": 10})


def test_closed_breaker_allows_success():
    breaker = CircuitBreaker(policy())
    assert call_with_breaker(breaker, lambda: "ok", now=0)["ok"] is True


def test_threshold_opens_breaker_after_failures():
    breaker = CircuitBreaker(policy())
    for now in (1, 2):
        call_with_breaker(breaker, lambda: (_ for _ in ()).throw(RuntimeError("down")), now=now)
    assert breaker.state == BreakerState.OPEN


def test_open_breaker_rejects_before_reset_window():
    breaker = CircuitBreaker(policy(), state=BreakerState.OPEN, opened_at=5)
    assert call_with_breaker(breaker, lambda: "unused", now=8)["reason"] == "breaker_open"


def test_half_open_allows_first_probe_after_reset():
    breaker = CircuitBreaker(policy(), state=BreakerState.OPEN, opened_at=0)
    assert call_with_breaker(breaker, lambda: "ok", now=11)["state"] == "closed"


def test_half_open_rejects_second_probe_while_first_in_flight():
    breaker = CircuitBreaker(policy(), state=BreakerState.HALF_OPEN, in_flight_probe=True)
    assert breaker.allow_request(now=12) is False


def test_failed_probe_reopens_breaker():
    breaker = CircuitBreaker(policy(), state=BreakerState.HALF_OPEN)
    call_with_breaker(breaker, lambda: (_ for _ in ()).throw(RuntimeError("down")), now=12)
    assert breaker.state == BreakerState.OPEN


def test_successful_probe_resets_failures():
    breaker = CircuitBreaker(policy(), state=BreakerState.HALF_OPEN, failures=2)
    call_with_breaker(breaker, lambda: "ok", now=12)
    assert breaker.failures == 0


def test_closed_success_clears_old_failure_count():
    breaker = CircuitBreaker(policy(), failures=1)
    call_with_breaker(breaker, lambda: "ok", now=1)
    assert breaker.failures == 0


def test_response_shape_for_rejection_is_stable():
    breaker = CircuitBreaker(policy(), state=BreakerState.OPEN, opened_at=100)
    assert set(call_with_breaker(breaker, lambda: "x", now=101)) == {"ok", "state", "reason"}


def test_common_wrong_fix_does_not_allow_unbounded_half_open_probes():
    breaker = CircuitBreaker(policy(), state=BreakerState.HALF_OPEN, in_flight_probe=True)
    assert call_with_breaker(breaker, lambda: "extra", now=20).get("reason") == "breaker_open"
